import $ from 'jquery'
import katex from 'katex'
import React, { useEffect, useRef, useState } from 'react'
import ReactQuill, { Quill } from 'react-quill'
import BlotFormatter from 'quill-blot-formatter'
import { IEditor } from '../interface'

declare global {
  interface Window {
    katex: typeof katex
    jQuery: JQueryStatic
    $: JQueryStatic
  }
}

type Mathquill4quill = (arg0: {
  Quill: typeof Quill
  katex: typeof katex
}) => (
  quill: ReturnType<ReactQuill['getEditor']>,
  options: { operators: Array<[string, string]>; displayHistory: boolean }
) => void

let mathquill4quill: Mathquill4quill
if (typeof window !== 'undefined') {
  window.katex = katex
  window.jQuery = window.$ = $
  mathquill4quill = require('mathquill4quill') as Mathquill4quill
  require('@edtr-io/mathquill/build/mathquill.js')
}

Quill.register('modules/blotFormatter', BlotFormatter)

const customOperator: Array<[string, string]> = [
  ['\\pm', '\\pm'],
  ['\\sqrt{x}', '\\sqrt'],
  ['\\sqrt[3]{x}', '\\sqrt[3]{}'],
  ['\\sqrt[n]{x}', '\\nthroot'],
  ['\\frac{x}{y}', '\\frac'],
  ['\\sum^{s}_{x}{d}', '\\sum'],
  ['\\prod^{s}_{x}{d}', '\\prod'],
  ['\\coprod^{s}_{x}{d}', '\\coprod'],
  ['\\int^{s}_{x}{d}', '\\int'],
  ['\\binom{n}{k}', '\\binom']
]

const QuillEditor = (props: IEditor) => {
  const defaultToolbar = [
    ['bold', 'italic', 'underline', 'strike'], // toggled buttons
    ['blockquote', 'code-block'],

    [{ list: 'ordered' }, { list: 'bullet' }],
    [{ script: 'sub' }, { script: 'super' }], // superscript/subscript
    [{ header: [1, 2, 3, false] }],
    [{ direction: 'rtl' }],
    ['link', 'image', 'formula'],

    [{ color: [] }, { background: [] }], // dropdown with defaults from theme
    [{ align: [] }],

    ['clean'] // remove formatting button
  ]

  const reactQuill = useRef<ReactQuill | null>(null)

  const [editorHtml, setEditorHtml] = useState('')

  let didAttachQuillRefs = false
  const attachQuillRefs = () => {
    if (!didAttachQuillRefs) {
      const enableMathQuillFormulaAuthoring = mathquill4quill({ Quill, katex })
      const editor = reactQuill.current?.getEditor()
      if (!editor) return

      enableMathQuillFormulaAuthoring(editor, {
        operators: props.customOperator || customOperator,
        displayHistory: true
      })
      didAttachQuillRefs = true
    }
  }

  useEffect(() => {
    attachQuillRefs()
  }, [])

  useEffect(() => {
    if (props.initialValue) {
      setEditorHtml(props.initialValue)
    }
  }, [props.initialValue])

  useEffect(() => {
    if (props.resetField) {
      setEditorHtml('')
      props.setResetField && props.setResetField(false)
    }
  }, [props.resetField])

  const handleChange = (value: string) => {
    setEditorHtml(value)
    props.onChange && props.onChange(value)
  }

  return (
    <ReactQuill
      ref={reactQuill}
      modules={{
        formula: true,
        toolbar: props.toolbar || defaultToolbar,
        clipboard: {
          // toggle to add extra line breaks when pasting HTML:
          matchVisual: false
        },
        blotFormatter: {}
      }}
      value={editorHtml}
      onChange={handleChange}
      onBlur={props.onBlur}
      theme={props.theme || 'snow'}
      placeholder={props.placeholder || 'Write something..'}
      bounds='.quill'
      readOnly={props.readOnly}
    />
  )
}

export default QuillEditor
